'use client';

/**
 * Hallway (room directory) backed by Convex.
 * Replaces: use-hallway-socket.ts (Socket.io) + REST /api/v1/rooms.
 *
 * NOTE: requires `npx convex dev` to have generated convex/_generated/.
 */
import { useQuery, useMutation } from 'convex/react';
// @ts-expect-error - generated by `npx convex dev`
import { api } from '@/convex/_generated/api';
import { getDeviceId, getNickname } from '@/lib/guest';

export function useRoomDirectory(language?: string) {
  const rooms = useQuery(api.rooms.list, { language });
  return { rooms, isLoading: rooms === undefined };
}

export function useCreateRoom() {
  const create = useMutation(api.rooms.create);
  return async (input: {
    name: string;
    language: string;
    topic?: string;
    level?: string;
    mode: 'voice' | 'stage' | 'private';
    nickname: string;
  }) => {
    return await create({
      ...input,
      deviceId: getDeviceId(),
      nickname: input.nickname || getNickname() || 'Guest',
    });
  };
}
